 "content": "from collections import Counter


def transform(grid):
    """Map the more frequent input color to 2 and the less frequent to 0."""
    counts = Counter(value for row in grid for value in row)
    if len(counts) != 2:
        raise ValueError("expected exactly two input colors")
    majority = counts.most_common(1)[0][0]
    return [[2 if value == majority else 0 for value in row] for row in grid]
