 "content": "def transform(grid):
    """The symbol 5 is recolored to the other palette color; the other color becomes 0."""
    colors = {value for row in grid for value in row}
    if len(colors) != 2 or 5 not in colors:
        raise ValueError("expected a two-color grid containing color 5")
    replacement = next(color for color in colors if color != 5)
    return [[replacement if value == 5 else 0 for value in row] for row in grid]
